use serde_json::{Value, from_str};

pub fn solve(input: Value) -> Value {
    let input_arr = from_str::<Vec<Vec<i64>>>(input.to_string().as_str()).unwrap();
    let mut server_time = 0;
    let mut total_wait = 0;

    for job in input_arr {
        let (arrival, duration) = (job[0], job[1]);
        server_time = server_time.max(arrival);
        total_wait += server_time - arrival;
        server_time += duration;
    }

    Value::Number(total_wait.into())
}
